@extends('layouts.app') @section('title','Panier') @section('content')<h1>Votre panier</h1>@if(count($cart))<div class="panel">@foreach($cart as $id=>$line)@if(isset($products[$id]))<div class="cart-row"><div><strong>{{ $products[$id]->name }}</strong><p>{{ number_format((float)$products[$id]->price($currency),2) }} {{ $currency }}</p></div><form method="post" action="{{ route('cart.update',$products[$id]) }}" class="inline">@csrf @method('PATCH')<input type="number" name="quantity" min="1" max="{{ $products[$id]->stock }}" value="{{ $line['quantity'] }}"><button class="btn small secondary">Actualiser</button></form><form method="post" action="{{ route('cart.remove',$products[$id]) }}">@csrf @method('DELETE')<button class="link danger">Retirer</button></form></div>@endif @endforeach<hr><h2>Total : {{ number_format($total,2) }} {{ $currency }}</h2><a class="btn" href="{{ route('checkout') }}">Passer la commande</a></div>@else<p>Votre panier est vide.</p><a class="btn" href="{{ route('products.index') }}">Découvrir les produits</a>@endif@endsection
